package local.tvmorph.tv;import android.content.Context;import org.json.*;
public class PlaybackHistoryCheck{public static void main(String[] args)throws Exception{Context c=new Context();UiSettings.prefs(c).edit().putString("viewerId","default").apply();JSONObject film=new JSONObject().put("id","1").put("kind","vod").put("name","Film").put("url","DO_NOT_STORE_STREAM_URL").put("password","DO_NOT_STORE_PASSWORD");PlaybackHistory.remember(c,"account",film);PlaybackHistory.remember(c,"account",film);JSONArray history=PlaybackHistory.entries(c,"account");if(history.length()!=1||history.toString().contains("DO_NOT_STORE"))throw new AssertionError(history.toString());UiSettings.prefs(c).edit().putString("viewerId","vother").apply();if(PlaybackHistory.entries(c,"account").length()!=0)throw new AssertionError("Viewer leaked");PlaybackHistory.remember(c,"account",new JSONObject().put("id","2").put("kind","episode").put("name","Episode"));if(PlaybackHistory.entries(c,"anotherAccount").length()!=0)throw new AssertionError("Account leaked");UiSettings.prefs(c).edit().putString("viewerId","default").apply();if(PlaybackHistory.entries(c,"account").length()!=1)throw new AssertionError("Old viewer lost");for(int i=2;i<=215;i++)PlaybackHistory.remember(c,"account",new JSONObject().put("id",String.valueOf(i)).put("kind","vod").put("name","Film "+i));history=PlaybackHistory.entries(c,"account");if(history.length()!=200||!history.getJSONObject(0).getString("id").equals("215"))throw new AssertionError();System.out.println("PASS native history: deduplicated, bounded to 200, newest first, viewer/account isolation, stream URL and password never indexed.");}}
